46-/// - Not reproduced: Claude Code cuts a name longer than 200
47-///   characters to 200 and appends a hash of the path.
48-/// - Source: the installed Claude Code binary, version 2.1.295,
49-///   read 2026-10-09.
50:pub fn encode_path(path: &str) -> String {
51-    let mut name = String::with_capacity(path.len());
52-    for c in path.chars() {
53-        if c.is_ascii_alphanumeric() {
54-            name.push(c);
55-        } else {
56-            (0..c.len_utf16()).for_each(|_| name.push('-'));
57-        }
58-    }
59-    name
60-}
61-
62-/// Read what exists at a path without following symlinks.
63-///
64-/// Returns:
65-/// - `None`: nothing exists
66-/// - `Some(None)`: exists but is not a symlink
67-/// - `Some(Some(target))`: symlink pointing to target
68-fn probe(path: &Path) -> Option<Option<PathBuf>> {
69-    match path.symlink_metadata() {
70-        Err(_) => None,
71-        Ok(meta) => {
72-            if meta.is_symlink() {
73-                // OK: TOCTOU race after symlink_metadata, so an empty PathBuf forces recreate
74-                Some(Some(std::fs::read_link(path).unwrap_or_default()))
75-            } else {
76-                Some(None)
77-            }
78-        }
79-    }
80-}
